exercise.solution:
function parseUrl(address) {
  const url = new URL(address);

  return {
    protocol: url.protocol.replace(':', ''),
    host: url.hostname,
    path: url.pathname,
    query: Object.fromEntries(url.searchParams.entries())
  };
}
